import pandas as pd
import pdfplumber
import re
import json
from difflib import SequenceMatcher

def fuzzy_match(name, choices, threshold=0.8):
    best_match = None
    best_score = 0
    for choice in choices:
        score = SequenceMatcher(None, name.lower(), choice.lower()).ratio()
        if score > best_score:
            best_score = score
            best_match = choice
    if best_score >= threshold:
        return best_match
    return None

def solve():
    # Load vendors
    vendors_df = pd.read_excel('vendors.xlsx')
    # Create a mapping from name to vendor info
    vendors = {}
    for _, row in vendors_df.iterrows():
        vendors[row['name']] = {'id': row['id'], 'iban': row['iban']}

    vendor_names = list(vendors.keys())

    # Load purchase orders
    po_df = pd.read_csv('purchase_orders.csv')
    purchase_orders = {}
    for _, row in po_df.iterrows():
        purchase_orders[str(row['po_number'])] = {'vendor_id': row['vendor_id'], 'amount': row['amount']}

    fraud_report = []

    with pdfplumber.open('invoices.pdf') as pdf:
        for i, page in enumerate(pdf.pages):
            page_number = i + 1
            text = page.extract_text()
            if not text:
                continue

            # Extraction
            vendor_name_match = re.search(r'From:\s*(.*)', text)
            amount_match = re.search(r'Total\s*\$([\d.]+)', text)
            iban_match = re.search(r'Payment IBAN:\s*(\w+)', text)
            po_match = re.search(r'PO Number:\s*([\w-]+)', text)

            invoice_vendor_name = vendor_name_match.group(1).strip() if vendor_name_match else None
            invoice_amount = float(amount_match.group(1)) if amount_match else 0.0
            invoice_iban = iban_match.group(1).strip() if iban_match else None
            invoice_po = po_match.group(1).strip() if po_match else None

            reason = None

            # 1. Unknown Vendor
            matched_vendor_name = fuzzy_match(invoice_vendor_name, vendor_names)
            if not matched_vendor_name:
                reason = "Unknown Vendor"
            else:
                matched_vendor = vendors[matched_vendor_name]
                # 2. IBAN Mismatch
                if invoice_iban != matched_vendor['iban']:
                    reason = "IBAN Mismatch"
                else:
                    # 3. Invalid PO
                    if invoice_po not in purchase_orders:
                        reason = "Invalid PO"
                    else:
                        po_data = purchase_orders[invoice_po]
                        # 4. Amount Mismatch
                        if abs(invoice_amount - po_data['amount']) > 0.01:
                            reason = "Amount Mismatch"
                        # 5. Vendor Mismatch
                        elif po_data['vendor_id'] != matched_vendor['id']:
                            reason = "Vendor Mismatch"

            if reason:
                fraud_report.append({
                    "invoice_page_number": page_number,
                    "vendor_name": invoice_vendor_name,
                    "invoice_amount": invoice_amount,
                    "iban": invoice_iban,
                    "po_number": invoice_po,
                    "reason": reason
                })

    with open('fraud_report.json', 'w') as f:
        json.dump(fraud_report, f, indent=2)

if __name__ == "__main__":
    solve()

